#!/usr/bin/env bash
# owner: @camunda/reliability-testing
#
# Commits the change of load-tests/setup/<folder>/versions.yaml on the branch
# release-load-test/<folder>, force-pushes the branch and opens the pull request that targets main,
# or updates the open one for that branch. Nothing happens when the file has no change.
#
# Usage: load-test-open-release-pull-request.sh <folder> <orchestration-tag> <optimize-tag> <identity-tag> <connectors-tag>
#   An empty optimize, identity or connectors tag is shown as unchanged in the pull request.
#
# Environment:
#   GITHUB_ACTOR, GITHUB_ACTOR_ID  User of the commit
#   GITHUB_WORKFLOW, GITHUB_RUN_ID  Run that is named in the commit message
#   GITHUB_REPOSITORY               Repository of the pull request
#   GH_TOKEN                        Token that pushes the branch and opens the pull request
#   SETUP_DIR                       Optional: setup directory (default: load-tests/setup)

set -euo pipefail

folder="$1"
orchestration_tag="$2"
optimize_tag="${3:-}"
identity_tag="${4:-}"
connectors_tag="${5:-}"
setup_dir="${SETUP_DIR:-load-tests/setup}"

: "${GITHUB_ACTOR:?GITHUB_ACTOR is required}"
: "${GITHUB_ACTOR_ID:?GITHUB_ACTOR_ID is required}"
: "${GITHUB_WORKFLOW:?GITHUB_WORKFLOW is required}"
: "${GITHUB_RUN_ID:?GITHUB_RUN_ID is required}"
: "${GITHUB_REPOSITORY:?GITHUB_REPOSITORY is required}"

file="${setup_dir}/${folder}/versions.yaml"
if git diff --quiet -- "${file}"; then
  echo "${file} already holds these tags on main."
  exit 0
fi

branch="release-load-test/${folder}"
title="ci: run ${orchestration_tag} in the ${folder} release load test"

git switch -C "${branch}"
git config user.name "${GITHUB_ACTOR}"
git config user.email "${GITHUB_ACTOR_ID}+${GITHUB_ACTOR}@users.noreply.github.com"
git add "${file}"
git commit -m "${title}" \
  -m "Updates ${file} for the release ${orchestration_tag}." \
  -m "Generated by the workflow ${GITHUB_WORKFLOW} (run ${GITHUB_RUN_ID})."
git push --force origin "${branch}"

cell() { if [[ -n "$1" ]]; then echo "\`$1\`"; else echo "unchanged"; fi; }
body_file=$(mktemp)
{
  echo "Updates \`${file}\` for the release \`${orchestration_tag}\`."
  echo
  echo "The release load test of this folder uses the new tags after this pull request is merged."
  echo
  echo "| Component | Tag |"
  echo "|---|---|"
  echo "| Camunda | \`${orchestration_tag}\` |"
  echo "| Optimize | $(cell "${optimize_tag}") |"
  echo "| Identity | $(cell "${identity_tag}") |"
  echo "| Connectors | $(cell "${connectors_tag}") |"
  echo
  echo "## Related issues"
  echo
  echo "- [x] This PR does not need a linked issue"
} > "${body_file}"

existing=$(gh pr list --repo "${GITHUB_REPOSITORY}" --head "${branch}" --base main --state open \
  --json number --jq '.[0].number // empty')
if [[ -n "${existing}" ]]; then
  gh pr edit "${existing}" --repo "${GITHUB_REPOSITORY}" --title "${title}" --body-file "${body_file}"
  echo "Updated pull request #${existing}"
else
  # The label makes load-test-golden-update.yml regenerate the golden files for the new tags.
  gh pr create --repo "${GITHUB_REPOSITORY}" --base main --head "${branch}" \
    --title "${title}" --body-file "${body_file}" --label generate-golden
fi
